  1 | /* 🦙 Llama Player - Winamp Nostalgic Theme */
  2 | 
  3 | :root {
  4 |   --winamp-bg: #1a1a2e;
  5 |   --winamp-primary: #2d2d4a;
  6 |   --winamp-secondary: #3a3a5c;
  7 |   --winamp-accent: #00ff88;
  8 |   --winamp-accent-dim: #00aa55;
  9 |   --winamp-highlight: #ff6b9d;
 10 |   --winamp-text: #e0e0e0;
 11 |   --winamp-text-dim: #8888aa;
 12 |   --winamp-border: #4a4a6a;
 13 |   --winamp-progress-bg: #0d0d1a;
 14 |   --winamp-progress-fill: linear-gradient(90deg, #00ff88, #00ccff);
 15 |   --winamp-shadow: rgba(0, 0, 0, 0.6);
 16 |   --font-mono: "Courier New", monospace;
 17 |   --title-bar-height: 32px;
 18 |   --status-bar-height: 28px;
 19 |   --border-radius: 4px;
 20 | }
 21 | 
 22 | * {
 23 |   margin: 0;
 24 |   padding: 0;
 25 |   box-sizing: border-box;
 26 | }
 27 | 
 28 | body {
 29 |   font-family: var(--font-mono);
 30 |   background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a14 100%);
 31 |   color: var(--winamp-text);
 32 |   min-height: 100vh;
 33 |   display: flex;
 34 |   justify-content: center;
 35 |   align-items: center;
 36 | }
 37 | 
 38 | #root {
 39 |   width: 100%;
 40 |   max-width: 480px;
 41 |   padding: 16px;
 42 | }
 43 | 
 44 | /* ===== App Container ===== */
 45 | 
 46 | .app {
 47 |   background: var(--winamp-bg);
 48 |   border: 2px solid var(--winamp-border);
 49 |   border-radius: var(--border-radius);
 50 |   overflow: hidden;
 51 |   box-shadow: 0 8px 32px var(--winamp-shadow);
 52 | }
 53 | 
 54 | /* ===== Title Bar ===== */
 55 | 
 56 | .title-bar {
 57 |   display: flex;
 58 |   align-items: center;
 59 |   justify-content: space-between;
 60 |   height: var(--title-bar-height);
 61 |   background: linear-gradient(90deg, var(--winamp-primary), var(--winamp-secondary));
 62 |   border-bottom: 1px solid var(--winamp-border);
 63 |   padding: 0 8px;
 64 |   user-select: none;
 65 | }
 66 | 
 67 | .title-bar-text {
 68 |   font-size: 12px;
 69 |   font-weight: bold;
 70 |   color: var(--winamp-accent);
 71 |   text-shadow: 0 0 8px rgba(0, 255, 136, 0.3);
 72 | }
 73 | 
 74 | .title-bar-controls {
 75 |   display: flex;
 76 |   gap: 4px;
 77 | }
 78 | 
 79 | .title-bar-controls button {
 80 |   width: 20px;
 81 |   height: 18px;
 82 |   border: 1px solid var(--winamp-border);
 83 |   border-radius: 2px;
 84 |   background: var(--winamp-primary);
 85 |   color: var(--winamp-text);
 86 |   font-size: 10px;
 87 |   cursor: pointer;
 88 |   display: flex;
 89 |   align-items: center;
 90 |   justify-content: center;
 91 |   transition: background 0.15s;
 92 | }
 93 | 
 94 | .title-bar-controls button:hover {
 95 |   background: var(--winamp-secondary);
 96 | }
 97 | 
 98 | .close-btn:hover {
 99 |   background: var(--winamp-highlight);
100 |   color: #fff;
101 | }
102 | 
103 | /* ===== Main Content ===== */
104 | 
105 | .main-content {
106 |   padding: 12px;
107 |   display: flex;
108 |   flex-direction: column;
109 |   gap: 12px;
110 | }
111 | 
112 | /* ===== Toolbar ===== */
113 | 
114 | .toolbar {
115 |   display: flex;
116 |   gap: 6px;
117 | }
118 | 
119 | .toolbar-btn {
120 |   display: flex;
121 |   align-items: center;
122 |   gap: 4px;
123 |   padding: 4px 10px;
124 |   font-family: var(--font-mono);
125 |   font-size: 11px;
126 |   border: 1px solid var(--winamp-border);
127 |   border-radius: var(--border-radius);
128 |   background: var(--winamp-primary);
129 |   color: var(--winamp-text);
130 |   cursor: pointer;
131 |   transition: all 0.15s;
132 | }
133 | 
134 | .toolbar-btn:hover {
135 |   background: var(--winamp-secondary);
136 |   border-color: var(--winamp-accent-dim);
137 | }
138 | 
139 | /* ===== Playlist Panel ===== */
140 | 
141 | .playlist-panel {
142 |   border: 1px solid var(--winamp-border);
143 |   border-radius: var(--border-radius);
144 |   background: var(--winamp-primary);
145 |   overflow: hidden;
146 | }
147 | 
148 | .panel-header {
149 |   background: linear-gradient(90deg, var(--winamp-secondary), var(--winamp-primary));
150 |   padding: 6px 10px;
151 |   font-size: 11px;
152 |   font-weight: bold;
153 |   color: var(--winamp-accent);
154 |   letter-spacing: 1px;
155 |   border-bottom: 1px solid var(--winamp-border);
156 | }
157 | 
158 | .playlist {
159 |   list-style: none;
160 |   max-height: 200px;
161 |   overflow-y: auto;
162 | }
163 | 
164 | .playlist-item {
165 |   display: flex;
166 |   align-items: center;
167 |   gap: 6px;
168 |   padding: 6px 10px;
169 |   font-size: 12px;
170 |   cursor: grab;
171 |   transition: background 0.1s, opacity 0.1s;
172 |   border-bottom: 1px solid rgba(74, 74, 106, 0.3);
173 |   user-select: none;
174 | }
175 | 
176 | .playlist-item:active {
177 |   cursor: grabbing;
178 | }
179 | 
180 | .playlist-item.dragging {
181 |   opacity: 0.4;
182 |   background: var(--winamp-secondary);
183 | }
184 | 
185 | .playlist-item.drag-over {
186 |   border-top: 2px solid var(--winamp-accent);
187 |   background: rgba(0, 255, 136, 0.08);
188 | }
189 | 
190 | .playlist-item:last-child {
191 |   border-bottom: none;
192 | }
193 | 
194 | .playlist-item:hover {
195 |   background: var(--winamp-secondary);
196 | }
197 | 
198 | .playlist-item.active {
199 |   background: var(--winamp-secondary);
200 |   color: var(--winamp-accent);
201 |   border-left: 3px solid var(--winamp-accent);
202 |   padding-left: 7px;
203 | }
204 | 
205 | .playlist-empty {
206 |   color: var(--winamp-text-dim);
207 |   cursor: default;
208 |   font-style: italic;
209 | }
210 | 
211 | .playlist-item-drag-handle {
212 |   width: 12px;
213 |   text-align: center;
214 |   font-size: 10px;
215 |   flex-shrink: 0;
216 |   color: var(--winamp-text-dim);
217 |   cursor: grab;
218 |   opacity: 0.5;
219 |   transition: opacity 0.15s;
220 | }
221 | 
222 | .playlist-item:hover .playlist-item-drag-handle {
223 |   opacity: 1;
224 | }
225 | 
226 | .playlist-item-icon {
227 |   width: 16px;
228 |   text-align: center;
229 |   font-size: 10px;
230 |   flex-shrink: 0;
231 | }
232 | 
233 | .playlist-item-title {
234 |   flex: 1;
235 |   white-space: nowrap;
236 |   overflow: hidden;
237 |   text-overflow: ellipsis;
238 | }
239 | 
240 | .playlist-item-artist {
241 |   color: var(--winamp-text-dim);
242 |   font-size: 10px;
243 |   max-width: 100px;
244 |   white-space: nowrap;
245 |   overflow: hidden;
246 |   text-overflow: ellipsis;
247 | }
248 | 
249 | .playlist-item-duration {
250 |   color: var(--winamp-text-dim);
251 |   font-size: 10px;
252 |   flex-shrink: 0;
253 |   margin-left: auto;
254 | }
255 | 
256 | .panel-footer {
257 |   display: flex;
258 |   justify-content: space-between;
259 |   padding: 4px 10px;
260 |   font-size: 10px;
261 |   color: var(--winamp-text-dim);
262 |   border-top: 1px solid var(--winamp-border);
263 |   background: rgba(0, 0, 0, 0.2);
264 | }
265 | 
266 | /* ===== Player Controls ===== */
267 | 
268 | .player-controls {
269 |   display: flex;
270 |   flex-direction: column;
271 |   gap: 8px;
272 | }
273 | 
274 | .now-playing {
275 |   display: flex;
276 |   align-items: center;
277 |   gap: 10px;
278 |   padding: 6px 0;
279 | }
280 | 
281 | .album-art {
282 |   width: 48px;
283 |   height: 48px;
284 |   border-radius: var(--border-radius);
285 |   border: 1px solid var(--winamp-border);
286 |   object-fit: cover;
287 |   flex-shrink: 0;
288 |   background: var(--winamp-primary);
289 | }
290 | 
291 | .now-playing-info {
292 |   flex: 1;
293 |   min-width: 0;
294 | }
295 | 
296 | .track-title {
297 |   display: block;
298 |   font-size: 14px;
299 |   font-weight: bold;
300 |   color: var(--winamp-text);
301 |   white-space: nowrap;
302 |   overflow: hidden;
303 |   text-overflow: ellipsis;
304 | }
305 | 
306 | .track-artist {
307 |   display: block;
308 |   font-size: 11px;
309 |   color: var(--winamp-text-dim);
310 |   margin-top: 2px;
311 | }
312 | 
313 | .track-album {
314 |   display: block;
315 |   font-size: 10px;
316 |   color: var(--winamp-text-dim);
317 |   margin-top: 1px;
318 |   opacity: 0.7;
319 | }
320 | 
321 | .controls {
322 |   display: flex;
323 |   justify-content: center;
324 |   gap: 8px;
325 | }
326 | 
327 | .ctrl-btn {
328 |   width: 40px;
329 |   height: 32px;
330 |   border: 1px solid var(--winamp-border);
331 |   border-radius: var(--border-radius);
332 |   background: var(--winamp-primary);
333 |   color: var(--winamp-text);
334 |   font-size: 16px;
335 |   cursor: pointer;
336 |   display: flex;
337 |   align-items: center;
338 |   justify-content: center;
339 |   transition: all 0.15s;
340 | }
341 | 
342 | .ctrl-btn:hover {
343 |   background: var(--winamp-secondary);
344 |   border-color: var(--winamp-accent-dim);
345 | }
346 | 
347 | .ctrl-btn:active {
348 |   transform: scale(0.95);
349 | }
350 | 
351 | .play-btn {
352 |   width: 48px;
353 |   background: var(--winamp-accent-dim);
354 |   border-color: var(--winamp-accent);
355 |   color: #fff;
356 | }
357 | 
358 | .play-btn:hover {
359 |   background: var(--winamp-accent);
360 |   box-shadow: 0 0 12px rgba(0, 255, 136, 0.3);
361 | }
362 | 
363 | .shuffle-btn {
364 |   font-size: 14px;
365 | }
366 | 
367 | .shuffle-btn.active {
368 |   background: var(--winamp-accent-dim);
369 |   border-color: var(--winamp-accent);
370 |   color: #fff;
371 |   box-shadow: 0 0 8px rgba(0, 255, 136, 0.25);
372 | }
373 | 
374 | .shuffle-btn.active:hover {
375 |   background: var(--winamp-accent);
376 |   box-shadow: 0 0 12px rgba(0, 255, 136, 0.4);
377 | }
378 | 
379 | /* ===== Progress Bar ===== */
380 | 
381 | .progress-bar {
382 |   display: flex;
383 |   align-items: center;
384 |   gap: 8px;
385 |   padding: 4px 0;
386 | }
387 | 
388 | .progress-track {
389 |   flex: 1;
390 |   height: 8px;
391 |   background: var(--winamp-progress-bg);
392 |   border: 1px solid var(--winamp-border);
393 |   border-radius: 4px;
394 |   cursor: pointer;
395 |   position: relative;
396 |   overflow: hidden;
397 | }
398 | 
399 | .progress-thumb {
400 |   height: 100%;
401 |   background: var(--winamp-progress-fill);
402 |   border-radius: 3px;
403 |   transition: width 0.1s linear;
404 |   position: relative;
405 | }
406 | 
407 | .progress-thumb::after {
408 |   content: "";
409 |   position: absolute;
410 |   right: -2px;
411 |   top: -2px;
412 |   width: 8px;
413 |   height: 12px;
414 |   background: var(--winamp-text);
415 |   border-radius: 2px;
416 |   opacity: 0;
417 |   transition: opacity 0.15s;
418 | }
419 | 
420 | .progress-track:hover .progress-thumb::after {
421 |   opacity: 1;
422 | }
423 | 
424 | .time {
425 |   font-size: 11px;
426 |   color: var(--winamp-text-dim);
427 |   white-space: nowrap;
428 |   min-width: 80px;
429 |   text-align: right;
430 | }
431 | 
432 | /* ===== Status Bar ===== */
433 | 
434 | .status-bar {
435 |   display: flex;
436 |   align-items: center;
437 |   justify-content: space-between;
438 |   height: var(--status-bar-height);
439 |   background: linear-gradient(90deg, var(--winamp-primary), var(--winamp-secondary));
440 |   border-top: 1px solid var(--winamp-border);
441 |   padding: 0 10px;
442 |   font-size: 11px;
443 |   color: var(--winamp-text-dim);
444 | }
445 | 
446 | .volume-control {
447 |   display: flex;
448 |   align-items: center;
449 |   gap: 6px;
450 | }
451 | 
452 | .volume-icon {
453 |   font-size: 12px;
454 | }
455 | 
456 | .volume-slider {
457 |   width: 80px;
458 |   height: 4px;
459 |   -webkit-appearance: none;
460 |   appearance: none;
461 |   background: var(--winamp-progress-bg);
462 |   border: 1px solid var(--winamp-border);
463 |   border-radius: 2px;
464 |   outline: none;
465 |   cursor: pointer;
466 | }
467 | 
468 | .volume-slider::-webkit-slider-thumb {
469 |   -webkit-appearance: none;
470 |   width: 12px;
471 |   height: 12px;
472 |   background: var(--winamp-accent);
473 |   border: 1px solid var(--winamp-accent-dim);
474 |   border-radius: 2px;
475 |   cursor: pointer;
476 | }
477 | 
478 | .volume-slider::-moz-range-thumb {
479 |   width: 12px;
480 |   height: 12px;
481 |   background: var(--winamp-accent);
482 |   border: 1px solid var(--winamp-accent-dim);
483 |   border-radius: 2px;
484 |   cursor: pointer;
485 | }
486 | 
487 | /* ===== Scrollbar ===== */
488 | 
489 | ::-webkit-scrollbar {
490 |   width: 8px;
491 | }
492 | 
493 | ::-webkit-scrollbar-track {
494 |   background: var(--winamp-bg);
495 |   border-left: 1px solid var(--winamp-border);
496 | }
497 | 
498 | ::-webkit-scrollbar-thumb {
499 |   background: var(--winamp-primary);
500 |   border: 1px solid var(--winamp-border);
501 |   border-radius: 2px;
502 | }
503 | 
504 | ::-webkit-scrollbar-thumb:hover {
505 |   background: var(--winamp-secondary);
506 | }
507 | 
508 | /* ===== Selection ===== */
509 | 
510 | ::selection {
511 |   background: var(--winamp-accent);
512 |   color: var(--winamp-bg);
513 | }
